    ('Manager {0} verwijderen', 'Delete manager {0}', 'Manager {0} löschen'),
    ('Ceph raadt stoppen nu af: {0}', 'Ceph advises against stopping now: {0}', 'Ceph rät jetzt vom Stoppen ab: {0}'),
