assert len({row[0] for row in TABLE}) == len(TABLE), sorted(r[0] for r in TABLE if [x[0] for x in TABLE].count(r[0]) > 1)
import re as _re
for _nl, _en, _de in TABLE:
    _ph = lambda s: sorted(set(_re.findall(r"\{\d\}", s)))  # noqa: E731
    assert _ph(_nl) == _ph(_en) == _ph(_de), _nl


def js(lang: int) -> dict:
    """{nederlands: vertaling} voor taal 1 (Engels) of 2 (Duits); gelijke teksten worden weggelaten."""
    return {row[0]: row[lang] for row in TABLE if row[lang] != row[0]}
